import{_ as e,a as t,b as o,c as r,d,e as n}from"./chunks/ee-ohos-12.YBQ8g5AA.js";import{_ as s}from"./chunks/ee-ohos-2.C7lmEPa0.js";import{_ as i,o as l,c,a3 as p}from"./chunks/framework.B5WAEDB7.js";const _=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction"},"headers":[],"relativePath":"11.harmonyos/00.introduction.md","filePath":"11.harmonyos/00.introduction.md","lastUpdated":1786613910000}'),f={name:"11.harmonyos/00.introduction.md"};function m(u,a,g,v,h,b){return l(),c("div",null,[...a[0]||(a[0]=[p('<div class="hero" data-v-2e9afd01><div class="hero-badges" data-v-2e9afd01><span class="badge badge--star" data-v-2e9afd01>⭐ 8000+ Star</span><span class="badge badge--version" data-v-2e9afd01>🚀 v5</span><span class="badge badge--ohos" data-v-2e9afd01>🪶 HarmonyOS</span></div><h1 class="hero-title" data-v-2e9afd01>ElectronEgg: v5 Upgrade — Easily Build HarmonyOS Apps</h1><div class="hero-actions" data-v-2e9afd01><a class="btn btn--primary" href="https://github.com/dromara/electron-egg" target="_blank" rel="noopener" data-v-2e9afd01>GitHub Repo →</a><a class="btn btn--ghost" href="#wrapping-up" data-v-2e9afd01>Join Community</a></div></div><blockquote data-v-2e9afd01><p data-v-2e9afd01>One codebase, packaged for Windows, Mac, and Linux — and now it runs directly on HarmonyOS. ElectronEgg v5 brings HarmonyOS support.</p></blockquote><h2 id="introduction" tabindex="-1" data-v-2e9afd01>Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;" data-v-2e9afd01>​</a></h2><p data-v-2e9afd01>Since it was open-sourced, <a href="https://github.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-2e9afd01>ElectronEgg</a>&#39;s vision has stayed simple: <strong data-v-2e9afd01>empower every developer to master desktop software development</strong>. It brings front-end and back-end engineering practices into desktop development, wrapping Electron&#39;s complexity behind a clean controller / service / preload layered architecture. The framework has now amassed <strong data-v-2e9afd01>8000+ Stars</strong> across the web, validated by long-term use across many teams — you can use it with confidence.</p><p data-v-2e9afd01>Building on this, v5 delivers a major upgrade — and one of its headline capabilities is: <strong data-v-2e9afd01>effortlessly build HarmonyOS apps</strong>.</p><p data-v-2e9afd01>After repeated attempts, we finally got ElectronEgg running on HarmonyOS devices. It&#39;s still in the <strong data-v-2e9afd01>testing phase</strong>, but the entire workflow already works end to end — see the screenshots below.</p><h2 id="harmonyos-support-one-codebase-running-on-harmonyos" tabindex="-1" data-v-2e9afd01>HarmonyOS Support: One Codebase, Running on HarmonyOS <a class="header-anchor" href="#harmonyos-support-one-codebase-running-on-harmonyos" aria-label="Permalink to &quot;HarmonyOS Support: One Codebase, Running on HarmonyOS&quot;" data-v-2e9afd01>​</a></h2><p data-v-2e9afd01>In the past, porting an Electron app to HarmonyOS essentially meant &quot;rewriting it from scratch&quot;. v5 automatically extracts your build artifacts into the HarmonyOS HAP, where they are loaded by the HAP project&#39;s web engine. <strong data-v-2e9afd01>Your existing ElectronEgg business code runs as a HarmonyOS app with almost no changes.</strong></p><p data-v-2e9afd01>Below are real screenshots of the ElectronEgg demo app running on HarmonyOS:</p><blockquote data-v-2e9afd01><p data-v-2e9afd01>App installed on the HarmonyOS system</p></blockquote><div class="center-logo" data-v-2e9afd01><img src="'+e+'" alt="logo" data-v-2e9afd01></div><p data-v-2e9afd01><img src="'+t+'" alt="ElectronEgg demo in the HarmonyOS AppCenter" data-v-2e9afd01></p><blockquote data-v-2e9afd01><p data-v-2e9afd01>App launching</p></blockquote><p data-v-2e9afd01><img src="'+s+'" alt="ElectronEgg demo launching" data-v-2e9afd01></p><blockquote data-v-2e9afd01><p data-v-2e9afd01>Framework feature demo: communication, controllers, services and other capabilities work normally on HarmonyOS</p></blockquote><p data-v-2e9afd01><img src="'+o+'" alt="ElectronEgg demo feature showcase" data-v-2e9afd01></p><blockquote data-v-2e9afd01><p data-v-2e9afd01>Local image loading demo</p></blockquote><p data-v-2e9afd01><img src="'+r+'" alt="ElectronEgg demo feature showcase" data-v-2e9afd01></p><blockquote data-v-2e9afd01><p data-v-2e9afd01>Dock bar demo</p></blockquote><p data-v-2e9afd01><img src="'+d+'" alt="ElectronEgg demo feature showcase" data-v-2e9afd01></p><blockquote data-v-2e9afd01><p data-v-2e9afd01>Web page loading demo</p></blockquote><p data-v-2e9afd01><img src="'+n+'" alt="ElectronEgg demo feature showcase" data-v-2e9afd01></p><p data-v-2e9afd01>As you can see, a desktop app originally built for Windows / Mac runs smoothly on HarmonyOS — from installation to every feature. That&#39;s the core message of v5&#39;s HarmonyOS support: <strong data-v-2e9afd01>cross-platform is no longer a slogan; HarmonyOS is a first-class citizen.</strong></p><h2 id="what-else-is-new-in-v5" tabindex="-1" data-v-2e9afd01>What Else Is New in v5 <a class="header-anchor" href="#what-else-is-new-in-v5" aria-label="Permalink to &quot;What Else Is New in v5&quot;" data-v-2e9afd01>​</a></h2><p data-v-2e9afd01>Beyond HarmonyOS support, v5 also gives the framework core a fairly thorough refactor:</p><ul data-v-2e9afd01><li data-v-2e9afd01>Full TypeScript refactor: every API now has complete type definitions.</li><li data-v-2e9afd01>Dual module output: supports both CJS and ESM formats.</li><li data-v-2e9afd01>Pino logging: a more powerful logging system.</li><li data-v-2e9afd01>Bundle registry: faster startup.</li><li data-v-2e9afd01>Main-process bundling: main-process code can be bundled just like front-end code.</li><li data-v-2e9afd01>Build config overhaul: many fine-grained control options added.</li><li data-v-2e9afd01>Encryption upgrade: more secure.</li><li data-v-2e9afd01>ee-bin overhaul: now ships a complete TypeScript type system.</li></ul><h2 id="who-is-it-for" tabindex="-1" data-v-2e9afd01>Who Is It For <a class="header-anchor" href="#who-is-it-for" aria-label="Permalink to &quot;Who Is It For&quot;" data-v-2e9afd01>​</a></h2><ul data-v-2e9afd01><li data-v-2e9afd01>Developers who want to build desktop software with a front-end stack (Vue / React / HTML)</li><li data-v-2e9afd01>Teams that need to ship internal tools, admin consoles, or office software as desktop apps</li><li data-v-2e9afd01>Products that must cover Windows, Mac, Linux, <strong data-v-2e9afd01>and HarmonyOS</strong></li><li data-v-2e9afd01>Teams looking to lower Electron&#39;s learning curve and want a clear architecture</li></ul><p data-v-2e9afd01>Whether you&#39;re a front-end, back-end, ops, or client developer, you can get started quickly.</p><h2 id="wrapping-up" tabindex="-1" data-v-2e9afd01>Wrapping Up <a class="header-anchor" href="#wrapping-up" aria-label="Permalink to &quot;Wrapping Up&quot;" data-v-2e9afd01>​</a></h2><p data-v-2e9afd01>Desktop software — office tools, personal utilities — will remain a real, lasting need on the PC for the next decade. ElectronEgg exists to make building it simple, and now that simplicity extends to HarmonyOS.</p><p data-v-2e9afd01>The framework is already widely used in clients for accounting, government, enterprise, healthcare, education, stock trading, ERP, entertainment, video and more — feel free to use it with confidence.</p><div class="tip custom-block" data-v-2e9afd01><p class="custom-block-title" data-v-2e9afd01>Open Source &amp; Community</p><ul data-v-2e9afd01><li data-v-2e9afd01>GitHub: <a href="https://github.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-2e9afd01>https://github.com/dromara/electron-egg</a></li><li data-v-2e9afd01>Gitee: <a href="https://gitee.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-2e9afd01>https://gitee.com/dromara/electron-egg</a></li></ul></div><p data-v-2e9afd01>If it helps you, a Star is appreciated — and come join the community to chat.</p>',34)])])}const S=i(f,[["render",m],["__scopeId","data-v-2e9afd01"]]);export{_ as __pageData,S as default};
